/* Browser-only workflow sample. Money is never transferred by this page. */
const L=window.Lifecycle;L.prepare(state);
const lifeMyBase=myPage,lifeDetailBase=personDetail,lifeShellBase=adminShell,lifeRouteBase=route;
label.rejoin_requested='再参加申請中';
const refundStatus={planned:'返金予定（未送金）',recorded:'返金記録済み',cancelled:'予定取消済み'};
function lifeButton(action,p,text){return '<button type="button" class="btn btn-outline" data-life="'+action+'" data-id="'+p.id+'" data-revision="'+p.revision+'">'+text+'</button>';}
function ownLifecycle(p){let html='';const within=state.settings.clock<=state.settings.change;
 if(p.status==='cancel_requested')html='<h3>欠席申請を取り消す場合</h3><p>幹事の確認前なら、同じ申込番号のまま参加予定へ戻せます。定員と内容変更期限を確認します。</p>'+(within?lifeButton('withdraw',p,'欠席申請を取り消して出席に戻す'):'<p>内容変更期限を過ぎています。問い合わせフォームから幹事へご相談ください。</p>');
 if(p.status==='cancelled')html='<h3>もう一度参加を希望する場合</h3><p>再参加の希望を幹事へ送れます。定員・返金状況を確認してから承認します。新規申込は不要です。</p>'+(within?lifeButton('rejoin',p,'再参加を希望する'):'<p>内容変更期限を過ぎています。問い合わせフォームから幹事へご相談ください。</p>');
 if(p.status==='rejoin_requested')html='<p>再参加の希望を受け付けました。幹事の承認をお待ちください。入金・返金履歴と申込番号は引き継ぎます。</p>';
 const refunds=state.refunds.filter(x=>x.personId===p.id&&x.status!=='cancelled');if(refunds.length)html+='<h3>返金の状況</h3><p>入金確認の合計 '+yen(R.totalPaid(state,p.id))+' ／ 返金記録の合計 '+yen(L.refunded(state,p.id))+'</p>'+table(['返金額','状態','返金日'],refunds.map(x=>[yen(x.amount),refundStatus[x.status]+(x.status==='recorded'?(L.refundPaid(state,x.id)===x.amount?'（銀行照合済み）':'（銀行照合待ち）'):''),esc(x.refundDate||'未定')]));return html?'<section class="application-schedule" aria-label="欠席・再参加・返金のお手続き">'+html+'</section>':'';
}
myPage=function(){const html=lifeMyBase(),p=current();if(!p)return html;L.prepare(state);const box=document.createElement('div');box.innerHTML=html;box.querySelector('.registration-guide')?.insertAdjacentHTML('afterend',ownLifecycle(p));return box.innerHTML;};
adminShell=function(section,body){return lifeShellBase(section,body).replace('</nav>','<a href="#/admin/refunds" class="'+(section==='refunds'?'active':'')+'">欠席・再参加・返金</a></nav>');};
personDetail=function(id){lifeDetailBase(id);if(!organizer())return;document.querySelector('#modalBody [data-action="refund"]')?.remove();const p=state.people.find(p=>p.id===id);document.querySelector('#modalBody').insertAdjacentHTML('beforeend','<section class="panel"><h3>欠席・再参加・返金</h3>'+details([['入金合計',yen(R.totalPaid(state,id))],['返金記録済み',yen(L.refunded(state,id))],['返金予定',yen(L.planned(state,id))],['返金差引後の入金額',yen(L.netPaid(state,id))]])+(p.status==='rejoin_requested'?lifeButton('rejoin-approve',p,'再参加を承認する')+lifeButton('rejoin-reject',p,'今回は再参加を認めない'):'')+'<p><a href="#/admin/refunds/'+id+'" class="btn btn-outline" data-life="open-refunds">返金管理を開く</a></p></section>');};
function lifeForm(action,id,content,label){return '<form data-life-form="'+action+'" data-id="'+(id||0)+'">'+content+field('reason','処理理由・確認根拠')+'<p class="error-text" role="alert"></p><button class="btn" type="submit">'+label+'</button></form>';}
function refundAdminPage(pid){L.prepare(state);const candidates=state.people.filter(p=>['active','cancelled'].includes(p.status)&&L.available(state,p.id)>0);let body='<div class="panel"><h2>欠席・再参加の確認</h2><p>返金額は幹事が確認して入力します。キャンセル料は自動計算しません。送金は銀行側で別途行い、この画面では予定・実施内容・銀行照合を記録します。</p>'+table(['申込','状態','判断'],state.people.filter(p=>['cancel_requested','rejoin_requested'].includes(p.status)).map(p=>[esc(p.number+' '+p.name),esc(label[p.status]),p.status==='rejoin_requested'?lifeButton('rejoin-approve',p,'再参加を承認')+lifeButton('rejoin-reject',p,'今回は認めない'):'<button class="btn btn-outline" data-action="person-detail" data-id="'+p.id+'">欠席申請を確認</button>']))+'</div>';
 body+='<div class="panel"><h2>返金予定を登録する</h2><p>取消確定分または過払い分から、既存の返金予定・返金記録を引いた金額が上限です。実際の銀行口座情報はこのサンプルへ入力しないでください。</p>'+(candidates.length?lifeForm('plan',0,select('personId','返金する申込',candidates.map(p=>[p.id,p.number+' '+p.name+' ／ 登録可能 '+yen(L.available(state,p.id))]),pid||candidates[0].id)+field('amount','返金予定額（円）','','number')+'<input type="hidden" name="requestKey" value="'+crypto.randomUUID()+'">','返金予定を登録'):'<p>新しく返金予定を登録できる申込はありません。</p>')+'<p><button class="btn btn-outline" data-life="export-refunds">返金一覧CSV ↓</button></p></div>';
 const debits=state.transactions.filter(t=>t.state==='confirmed'&&t.debit>L.debitUsed(state,t.id));body+=state.refunds.slice().reverse().map(x=>{const p=state.people.find(p=>p.id===x.personId),matched=L.refundPaid(state,x.id);let ctl='';if(x.status==='planned')ctl=lifeForm('record',x.id,field('date','銀行で返金した日',state.settings.clock,'date')+field('reference','送金確認番号・確認メモ（口座番号は不要）'),'送金済みの内容を記録（送金操作ではありません）')+lifeForm('cancel-plan',x.id,'','未送金の予定を取り消す');if(x.status==='recorded'){if(matched<x.amount)ctl+=debits.length?lifeForm('link',x.id,select('transactionId','確認済み銀行出金',debits.map(t=>[t.id,'#'+t.id+' '+t.date+' '+yen(t.debit-L.debitUsed(state,t.id))+' '+t.memo]),debits[0].id)+field('amount','照合金額（円）',x.amount-matched,'number'),'銀行出金と照合する'):'<p>銀行CSVで出金を取り込み、確認済みにしてください。</p>';if(matched===0)ctl+=lifeForm('undo-record',x.id,'<p>誤記の訂正専用です。実際の送金は取り消されません。</p>','誤った返金記録を予定へ戻す');}return '<section class="panel"><h3>返金 #'+x.id+' ／ '+esc(p.number+' '+p.name)+' ／ '+yen(x.amount)+'</h3><p>'+esc(refundStatus[x.status]||x.status)+' ／ 銀行照合 '+yen(matched)+' ／ 返金日 '+esc(x.refundDate||'未定')+'</p><p>'+esc(x.reference||'')+'</p>'+ctl+'</section>';}).join('');body+='<div class="panel"><h2>返金と銀行出金の照合履歴</h2>'+table(['返金','出金明細','金額','状態','訂正'],state.refundLinks.map(a=>['#'+a.refundId,'#'+a.transactionId,yen(a.amount),a.active?'有効':'取消済',a.active?lifeForm('unlink',a.id,'','照合を取り消す'):'']))+'</div>';return adminShell('refunds',body);
}
route=function(){L.prepare(state);const path=location.hash.slice(1);if(/^\/admin\/refunds(?:\/|$)/.test(path)&&organizer()){renderSessionBar();main.innerHTML=refundAdminPage(Number(path.split('/')[3]||0));window.scrollTo(0,0);return;}lifeRouteBase();};window.removeEventListener('hashchange',lifeRouteBase);window.addEventListener('hashchange',route);
document.addEventListener('click',ev=>{const b=ev.target.closest('button[data-life],a[data-life]');if(!b)return;ev.preventDefault();ev.stopImmediatePropagation();const action=b.dataset.life;if(action==='open-refunds'){closeModal();location.hash=b.getAttribute('href').slice(1);return;}if(action==='export-refunds'){if(!organizer())return;download('同窓会_返金一覧.csv',R.toCSV([['返金ID','申込番号','氏名','金額','状態','返金日','確認メモ','銀行照合額'],...state.refunds.map(x=>[x.id,state.people.find(p=>p.id===x.personId)?.number,state.people.find(p=>p.id===x.personId)?.name,x.amount,refundStatus[x.status],x.refundDate,x.reference,L.refundPaid(state,x.id)])]));return;}const headings={withdraw:'欠席申請を取り消して出席に戻す',rejoin:'再参加を希望する','rejoin-approve':'再参加を承認する','rejoin-reject':'今回は再参加を認めない'};openModal('<h2>'+headings[action]+'</h2>'+lifeForm(action,Number(b.dataset.id),'<input type="hidden" name="revision" value="'+b.dataset.revision+'">','理由を付けて記録する'));},true);
document.addEventListener('submit',ev=>{const f=ev.target;if(!f.dataset.lifeForm)return;ev.preventDefault();ev.stopImmediatePropagation();const d=Object.fromEntries(new FormData(f)),id=Number(f.dataset.id),a=f.dataset.lifeForm;try{const uid=current()?.id;if(!uid)throw new Error('ログインが必要です。');change(s=>{if(a==='withdraw')return L.withdraw(s,id,d.revision,d.reason,uid);if(a==='rejoin')return L.requestRejoin(s,id,d.revision,d.reason,uid);if(a==='rejoin-approve'||a==='rejoin-reject')return L.decideRejoin(s,id,a==='rejoin-approve'?'approve':'reject',d.reason,uid);if(a==='plan')return L.planRefund(s,Number(d.personId),Number(d.amount),d.reason,d.requestKey,uid);if(a==='record')return L.recordRefund(s,id,d.date,d.reference,d.reason,uid);if(a==='cancel-plan')return L.cancelRefund(s,id,d.reason,uid);if(a==='undo-record')return L.undoRefund(s,id,d.reason,uid);if(a==='link')return L.linkRefund(s,id,Number(d.transactionId),Number(d.amount),d.reason,uid);if(a==='unlink')return L.unlinkRefund(s,id,d.reason,uid);throw new Error('不明な操作です。');});closeModal();route();toast('申込・返金と操作履歴を保存しました');}catch(e){f.querySelector('.error-text').textContent=e.message;}},true);
route();
